-- =============================================================================
-- RAG leve de legislação — Corpus Curado (Batch 6)
-- Prioridade 3: AFO/Finanças (51), Tributário (37), Civil (23), ECA (60),
--               Consumidor (72) e Crimes de Trânsito (59)
-- Arquivo: docs/migrations/legislacao_batch6.sql
--
-- Fontes Oficiais: Presidência da República (Planalto) e Constituição Federal.
-- Dispositivos atualizados e vigentes (CF/88, CTN, CC, CDC, ECA, CTB, LRF, LINDB).
-- Sem dispositivos revogados. Idempotente: on conflict (referencia) do update.
-- =============================================================================

insert into public.legislacao_artigos (referencia, texto, vigencia_de, id_materia, id_topico) values

-- -----------------------------------------------------------------------------
-- AFO E FINANÇAS PÚBLICAS (ID 51) — TÓPICO 435: Orçamento Público (CF/88)
-- -----------------------------------------------------------------------------
('CF/88 — art. 165 (caput)', 'Leis de iniciativa do Poder Executivo estabelecerão: I - o plano plurianual; II - as diretrizes orçamentárias; III - os orçamentos anuais. § 1º A lei que instituir o plano plurianual estabelecerá, de forma regionalizada, as diretrizes, objetivos e metas da administração pública federal para as despesas de capital e outras delas decorrentes e para as relativas aos programas de duração continuada. § 2º A lei de diretrizes orçamentárias compreenderá as metas e prioridades da administração pública federal, estabelecerá as diretrizes de política fiscal e respectivas metas, orientará a elaboração da lei orçamentária anual, disporá sobre as alterações na legislação tributária e estabelecerá a política de aplicação das agências financeiras oficiais de fomento. § 5º A lei orçamentária anual compreenderá: I - o orçamento fiscal; II - o orçamento de investimento das empresas em que a União, direta ou indiretamente, detenha a maioria do capital social com direito a voto; III - o orçamento da seguridade social.', '1988-10-05', 51, 435),
('CF/88 — art. 167', 'São vedados: I - o início de programas ou projetos não incluídos na lei orçamentária anual; II - a realização de despesas ou a assunção de obrigações diretas que excedam os créditos orçamentários ou adicionais; III - a realização de operações de créditos que excedam o montante das despesas de capital, ressalvadas as autorizadas mediante créditos suplementares ou especiais com finalidade precisa, aprovados pelo Poder Legislativo por maioria absoluta (regra de ouro); IV - a vinculação de receita de impostos a órgão, fundo ou despesa, ressalvadas a repartição do produto da arrecadação dos impostos a que se referem os arts. 158 e 159, a destinação de recursos para as ações e serviços públicos de saúde, para manutenção e desenvolvimento do ensino.', '1988-10-05', 51, 435),

-- -----------------------------------------------------------------------------
-- AFO E FINANÇAS PÚBLICAS (ID 51) — TÓPICO 389: LRF (Lei Complementar nº 101/2000)
-- -----------------------------------------------------------------------------
('LC nº 101/2000 — art. 1º, § 1º', 'A responsabilidade na gestão fiscal pressupõe a ação planejada e transparente, em que se previnem riscos e corrigem desvios capazes de afetar o equilíbrio das contas públicas, mediante o cumprimento de metas de resultados entre receitas e despesas e a obediência a limites e condições no que tange a renúncia de receita, geração de despesas com pessoal, da seguridade social e outras, dívidas consolidada e mobiliária, operações de crédito, inclusive por antecipação de receita, concessão de garantia e inscrição em Restos a Pagar.', '2000-05-04', 51, 389),
('LC nº 101/2000 — art. 14', 'A concessão ou ampliação de incentivo ou benefício de natureza tributária da qual decorra renúncia de receita deverá estar acompanhada de estimativa do impacto orçamentário-financeiro no exercício em que deva iniciar sua vigência e nos dois seguintes, atender ao disposto na lei de diretrizes orçamentárias e a pelo menos uma das seguintes condições: I - demonstração pelo proponente de que a renúncia foi considerada na estimativa de receita da lei orçamentária; ou II - estar acompanhada de medidas de compensação, no período mencionado no caput, por meio do aumento de receita, proveniente da elevação de alíquotas, ampliação da base de cálculo, majoração ou criação de tributo ou contribuição.', '2000-05-04', 51, 389),
('LC nº 101/2000 — art. 19', 'Para os fins do disposto no caput do art. 169 da Constituição, a despesa total com pessoal, em cada período de apuração e em cada ente da Federação, não poderá exceder os percentuais da receita corrente líquida, a seguir discriminados: I - União: 50% (cinquenta por cento); II - Estados: 60% (sessenta por cento); III - Municípios: 60% (sessenta por cento).', '2000-05-04', 51, 389),

-- -----------------------------------------------------------------------------
-- AFO E FINANÇAS PÚBLICAS (ID 51) — TÓPICO 390: Despesa Pública (Lei nº 4.320/1964)
-- -----------------------------------------------------------------------------
('Lei nº 4.320/1964 — art. 58', 'O empenho de despesa é o ato emanado de autoridade competente que cria para o Estado obrigação de pagamento pendente ou não de implemento de condição.', '1964-03-17', 51, 390),
('Lei nº 4.320/1964 — art. 60', 'É vedada a realização de despesa sem prévio empenho. § 1º Em casos especiais previstos na legislação determinada, será dispensada a emissão da nota de empenho.', '1964-03-17', 51, 390),
('Lei nº 4.320/1964 — art. 63', 'A liquidação da despesa consiste na verificação do direito adquirido pelo credor tendo por base os títulos e documentos comprobatórios do respectivo crédito. § 1° Essa verificação tem por fim apurar: I - a origem e o objeto do que se deve pagar; II - a importância exata a pagar; III - a quem se deve pagar a importância, para extinguir a obrigação.', '1964-03-17', 51, 390),
('Lei nº 4.320/1964 — art. 64', 'A ordem de pagamento é o despacho exarado por autoridade competente, determinando que a despesa liquidada seja paga.', '1964-03-17', 51, 390),

-- -----------------------------------------------------------------------------
-- DIREITO TRIBUTÁRIO (ID 37) — TÓPICO 399: Conceito de Tributo (CTN)
-- -----------------------------------------------------------------------------
('CTN — art. 3º', 'Tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sanção de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada.', '1966-10-25', 37, 399),
('CF/88 — art. 145', 'A União, os Estados, o Distrito Federal e os Municípios poderão instituir os seguintes tributos: I - impostos; II - taxas, em razão do exercício do poder de polícia ou pela utilização, efetiva ou potencial, de serviços públicos específicos e divisíveis, prestados ao contribuinte ou postos a sua disposição; III - contribuição de melhoria, decorrente de obras públicas.', '1988-10-05', 37, 399),

-- -----------------------------------------------------------------------------
-- DIREITO TRIBUTÁRIO (ID 37) — TÓPICO 549: Limitações ao Poder de Tributar (CF/88)
-- -----------------------------------------------------------------------------
('CF/88 — art. 150, I e II', 'Sem prejuízo de outras garantias asseguradas ao contribuinte, é vedado à União, aos Estados, ao Distrito Federal e aos Municípios: I - exigir ou aumentar tributo sem lei que o estabeleça (legalidade); II - instituir tratamento desigual entre contribuintes que se encontrem em situação equivalente, proibida qualquer distinção em razão de ocupação profissional ou função por eles exercida (isonomia);', '1988-10-05', 37, 549),
('CF/88 — art. 150, III', 'É vedado cobrar tributos: a) em relação a fatos geradores ocorridos antes do início da vigência da lei que os houver instituído ou aumentado (irretroatividade); b) no mesmo exercício financeiro em que haja sido publicada a lei que os instituiu ou aumentou (anterioridade anual); c) antes de decorridos noventa dias da data em que haja sido publicada a lei que os instituiu ou aumentou (anterioridade nonagesimal);', '1988-10-05', 37, 549),
('CF/88 — art. 150, VI', 'É vedado instituir impostos sobre: a) patrimônio, renda ou serviços, uns dos outros (imunidade recíproca); b) templos de qualquer culto; c) patrimônio, renda ou serviços dos partidos políticos, inclusive suas fundações, das entidades sindicais dos trabalhadores, das instituições de educação e de assistência social, sem fins lucrativos; d) livros, jornais, periódicos e o papel destinado a sua impressão.', '1988-10-05', 37, 549),

-- -----------------------------------------------------------------------------
-- DIREITO TRIBUTÁRIO (ID 37) — TÓPICO 380: Crédito Tributário (CTN)
-- -----------------------------------------------------------------------------
('CTN — art. 142', 'Compete privativamente à autoridade administrativa constituir o crédito tributário pelo lançamento, assim entendido o procedimento administrativo tendente a verificar a ocorrência do fato gerador da obrigação correspondente, determinar a matéria tributável, calcular o montante do tributo devido, identificar o sujeito passivo e, sendo caso, propor a aplicação da penalidade cabível. Parágrafo único. A atividade administrativa de lançamento é vinculada e obrigatória, sob pena de responsabilidade funcional.', '1966-10-25', 37, 380),
('CTN — art. 151', 'Suspendem a exigibilidade do crédito tributário: I - moratória; II - o depósito do seu montante integral; III - as reclamações e os recursos, nos termos das leis reguladoras do processo tributário administrativo; IV - a concessão de medida liminar em mandado de segurança; V - a concessão de medida liminar ou de tutela antecipada, em outras espécies de ação judicial; VI - o parcelamento.', '1966-10-25', 37, 380),
('CTN — art. 156', 'Extinguem o crédito tributário: I - o pagamento; II - a compensação; III - a transação; IV - remissão; V - a prescrição e a decadência; VI - a conversão de depósito em renda; VII - o pagamento antecipado e a homologação do lançamento; VIII - a consignação em pagamento; IX - a decisão administrativa irreformável; X - a decisão judicial passada em julgado; XI - a dação em pagamento em bens imóveis.', '1966-10-25', 37, 380),
('CTN — art. 175', 'Excluem o crédito tributário: I - a isenção; II - a anistia. Parágrafo único. A exclusão do crédito tributário não dispensa o cumprimento das obrigações acessórias dependentes da obrigação principal cujo crédito seja excluído, ou dela conseqüentes.', '1966-10-25', 37, 380),

-- -----------------------------------------------------------------------------
-- DIREITO CIVIL (ID 23) — TÓPICO 89: LINDB (Decreto-Lei nº 4.657/1942)
-- -----------------------------------------------------------------------------
('LINDB — art. 2º', 'Não se destinando à vigência temporária, a lei terá vigor até que outra a modifique ou revogue. § 1º A lei posterior revoga a anterior quando expressamente o declare, quando seja com ela incompatível ou quando regule inteiramente a matéria de que tratava a lei anterior. § 2º A lei nova, que estabeleça disposições gerais ou especiais a par das já existentes, não revoga nem modifica a lei anterior. § 3º Salvo disposição em contrário, a lei revogada não se restaura por ter a lei revogadora perdido a vigência (vedação da repristinação automática).', '1942-09-04', 23, 89),
('LINDB — art. 6º', 'A Lei em vigor terá efeito imediato e geral, respeitados o ato jurídico perfeito, o direito adquirido e a coisa julgada.', '1942-09-04', 23, 89),
('LINDB — art. 20, caput (incluído pela Lei nº 13.655/2018)', 'Nas esferas administrativa, controladora e judicial, não se decidirá com base em valores jurídicos abstratos sem que sejam consideradas as consequências práticas da decisão. Parágrafo único. A motivação demonstrará a necessidade e a adequação da medida imposta ou da invalidação de ato, contrato, ajuste, processo ou norma administrativa, inclusive em face das possíveis alternativas. (Incluído pela Lei nº 13.655, de 2018)', '2018-04-25', 23, 89),
('LINDB — art. 22 (incluído pela Lei nº 13.655/2018)', 'Na interpretação de normas sobre gestão pública, serão considerados os obstáculos e as dificuldades reais do gestor e as exigências das políticas públicas a seu cargo, sem prejuízo dos direitos dos administrados. (Incluído pela Lei nº 13.655, de 2018)', '2018-04-25', 23, 89),
('LINDB — art. 28 (incluído pela Lei nº 13.655/2018)', 'O agente público responderá pessoalmente por suas decisões ou opiniões técnicas em caso de dolo ou erro grosseiro. (Incluído pela Lei nº 13.655, de 2018)', '2018-04-25', 23, 89),

-- -----------------------------------------------------------------------------
-- DIREITO CIVIL (ID 23) — TÓPICO 518 e 379: Pessoas e Desconsideração (Código Civil)
-- -----------------------------------------------------------------------------
('CC — art. 2º', 'A personalidade civil da pessoa começa do nascimento com vida; mas a lei põe a salvo, desde a concepção, os direitos do nascituro.', '2002-01-10', 23, 518),
('CC — art. 3º', 'São absolutamente incapazes de exercer pessoalmente os atos da vida civil os menores de 16 (dezesseis) anos. (Redação dada pela Lei nº 13.146, de 2015 - Estatuto da Pessoa com Deficiência)', '2015-07-06', 23, 518),
('CC — art. 4º', 'São incapazes, relativamente a certos atos ou à maneira de os exercer: I - os maiores de dezesseis e menores de dezoito anos; II - os ébrios habituais e os viciados em tóxico; III - aqueles que, por causa transitória ou permanente, não puderem exprimir sua vontade; IV - os pródigos. Parágrafo único. A capacidade dos indígenas será regulada por legislação especial.', '2002-01-10', 23, 518),
('CC — art. 50 (caput)', 'Em caso de abuso da personalidade jurídica, caracterizado pelo desvio de finalidade ou pela confusão patrimonial, pode o juiz, a requerimento da parte, ou do Ministério Público quando lhe couber intervir no processo, desconsiderá-la para que os efeitos de certas e determinadas relações de obrigações sejam estendidos aos bens particulares de administradores ou de sócios da pessoa jurídica beneficiados direta ou indiretamente pelo abuso. (Redação dada pela Lei nº 13.874, de 2019 - Lei da Liberdade Econômica)', '2019-09-20', 23, 379),

-- -----------------------------------------------------------------------------
-- DIREITO CIVIL (ID 23) — TÓPICO 250: Responsabilidade Civil (Código Civil)
-- -----------------------------------------------------------------------------
('CC — art. 186', 'Aquele que, por ação ou omissão voluntária, negligência ou imprudência, violar direito e causar dano a outrem, ainda que exclusivamente moral, comete ato ilícito.', '2002-01-10', 23, 250),
('CC — art. 187', 'Também comete ato ilícito o titular de um direito que, ao exercê-lo, excede manifestamente os limites impostos pelo seu fim econômico ou social, pela boa-fé ou pelos bons costumes (abuso de direito).', '2002-01-10', 23, 250),
('CC — art. 927 (caput)', 'Aquele que, por ato ilícito (arts. 186 e 187), causar dano a outrem, fica obrigado a repará-lo. Parágrafo único. Haverá obrigação de reparar o dano, independentemente de culpa, nos casos especificados em lei, ou quando a atividade normalmente desenvolvida pelo autor do dano implicar, por sua natureza, risco para os direitos de outrem (responsabilidade objetiva).', '2002-01-10', 23, 250),

-- -----------------------------------------------------------------------------
-- ECA (ID 60) — TÓPICO 472: Ato Infracional e Medidas Socioeducativas (Lei nº 8.069/1990)
-- -----------------------------------------------------------------------------
('ECA — art. 2º', 'Considera-se criança, para os efeitos desta Lei, a pessoa até doze anos de idade incompletos, e adolescente aquela entre doze e dezoito anos de idade. Parágrafo único. Nos casos expressos em lei, aplica-se excepcionalmente este Estatuto às pessoas entre dezoito e vinte e um anos de idade.', '1990-07-13', 60, 472),
('ECA — art. 103', 'Considera-se ato infracional a conduta descrita como crime ou contravenção penal.', '1990-07-13', 60, 472),
('ECA — art. 104', 'São penalmente inimputáveis os menores de dezoito anos, sujeitos às medidas previstas nesta Lei. Parágrafo único. Para os efeitos desta Lei, deve ser considerada a idade do adolescente à data do fato.', '1990-07-13', 60, 472),
('ECA — art. 112', 'Verificada a prática de ato infracional, a autoridade competente poderá aplicar ao adolescente as seguintes medidas: I - advertência; II - obrigação de reparar o dano; III - prestação de serviços à comunidade; IV - liberdade assistida; V - inserção em regime de semiliberdade; VI - internação em estabelecimento educacional; VII - qualquer das medidas de proteção previstas no art. 101, I a VI.', '1990-07-13', 60, 472),
('ECA — art. 121', 'A internação constitui medida privativa da liberdade, sujeita aos princípios de brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento. § 2º A desinternação será precedida de autorização judicial, ouvido o Ministério Público. § 3º Em nenhuma hipótese o período máximo de internação excederá a três anos. § 5º A liberação será compulsória aos vinte e um anos de idade.', '1990-07-13', 60, 472),
('ECA — art. 131', 'O Conselho Tutelar é órgão permanente e autônomo, não jurisdicional, encarregado pela sociedade de zelar pelo cumprimento dos direitos da criança e do adolescente, definidos nesta Lei.', '1990-07-13', 60, 473),

-- -----------------------------------------------------------------------------
-- DIREITO DO CONSUMIDOR (ID 72) — TÓPICO 565: CDC (Lei nº 8.078/1990)
-- -----------------------------------------------------------------------------
('CDC — art. 2º', 'Consumidor é toda pessoa física ou jurídica que adquire ou utiliza produto ou serviço como destinatário final. Parágrafo único. Equipara-se a consumidor a coletividade de pessoas, ainda que indetermináveis, que haja intervindo nas relações de consumo.', '1990-09-11', 72, 565),
('CDC — art. 3º', 'Fornecedor é toda pessoa física ou jurídica, pública ou privada, nacional ou estrangeira, bem como os entes despersonalizados, que desenvolvem atividade de produção, montagem, criação, construção, transformação, importação, exportação, distribuição ou comercialização de produtos ou prestação de serviços.', '1990-09-11', 72, 565),
('CDC — art. 6º', 'São direitos básicos do consumidor: I - a proteção da vida, saúde e segurança contra os riscos provocados por produtos e serviços; III - a informação adequada e clara sobre os diferentes produtos e serviços, com especificação correta de quantidade, características, composição, qualidade, tributos incidentes e preço; IV - a proteção contra a publicidade enganosa e abusiva; VI - a efetiva prevenção e reparação de danos patrimoniais e morais; VIII - a facilitação da defesa de seus direitos, inclusive com a inversão do ônus da prova, a seu favor, no processo civil.', '1990-09-11', 72, 565),
('CDC — art. 12 (caput)', 'O fabricante, o produtor, o construtor, nacional ou estrangeiro, e o importador respondem, independentemente da existência de culpa, pela reparação dos danos causados aos consumidores por defeitos decorrentes de projeto, fabricação, construção, montagem, fórmulas, manipulação, apresentação ou acondicionamento de seus produtos, bem como por informações insuficientes ou inadequadas sobre sua utilização e riscos (responsabilidade pelo fato do produto).', '1990-09-11', 72, 565),
('CDC — art. 14 (caput)', 'O fornecedor de serviços responde, independentemente da existência de culpa, pela reparação dos danos causados aos consumidores por defeitos relativos à prestação dos serviços, bem como por informações insuficientes ou inadequadas sobre sua fruição e riscos. § 4º A responsabilidade pessoal dos profissionais liberais será apurada mediante a verificação de culpa.', '1990-09-11', 72, 565),
('CDC — art. 18 (caput)', 'Os fornecedores de produtos de consumo duráveis ou não duráveis respondem solidariamente pelos vícios de qualidade ou quantidade que os tornem impróprios ou inadequados ao consumo a que se destinam ou lhes diminuam o valor. § 1° Não sendo o vício sanado no prazo máximo de trinta dias, pode o consumidor exigir, alternativamente e à sua escolha: I - a substituição do produto por outro da mesma espécie; II - a restituição imediata da quantia paga, monetariamente atualizada, sem prejuízo de eventuais perdas e danos; III - o abatimento proporcional do preço.', '1990-09-11', 72, 565),
('CDC — art. 49', 'O consumidor pode desistir do contrato, no prazo de 7 dias a contar de sua assinatura ou do ato de recebimento do produto ou serviço, sempre que a contratação de fornecimento de produtos e serviços ocorrer fora do estabelecimento comercial, especialmente por telefone ou a domicílio (direito de arrependimento). Parágrafo único. Se o consumidor exercitar o direito de arrependimento previsto neste artigo, os valores eventualmente pagos, a qualquer título, durante o prazo de reflexão, serão devolvidos, de imediato, monetariamente atualizados.', '1990-09-11', 72, 565),

-- -----------------------------------------------------------------------------
-- LEGISLAÇÃO DE TRÂNSITO (ID 59) — TÓPICO 468: Crimes de Trânsito (Lei nº 9.503/1997 - CTB)
-- -----------------------------------------------------------------------------
('CTB — art. 302 (caput)', 'Praticar homicídio culposo na direção de veículo automotor: Pena - detenção, de dois a quatro anos, e suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor. § 3º Se o agente conduz veículo automotor sob a influência de álcool ou de qualquer outra substância psicoativa que determine dependência: Penas - reclusão, de cinco a oito anos, e suspensão ou proibição do direito de se obter a permissão ou a habilitação.', '1997-09-23', 59, 468),
('CTB — art. 303 (caput)', 'Praticar lesão corporal culposa na direção de veículo automotor: Penas - detenção, de seis meses a dois anos e suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor. § 2º Se o crime for praticado com a capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência, e do crime resultar lesão corporal de natureza grave ou gravíssima: Penas - reclusão, de dois a cinco anos.', '1997-09-23', 59, 468),
('CTB — art. 306 (caput)', 'Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência: Penas - detenção, de seis meses a três anos, multa e suspensão ou proibição de se obter a permissão ou a habilitação para dirigir veículo automotor. § 1º As condutas previstas no caput serão constatadas por: I - concentração igual ou superior a 6 decigramas de álcool por litro de sangue ou igual ou superior a 0,3 miligrama de álcool por litro de ar alveolar; ou II - sinais que indiquem, na forma disciplinada pelo Contran, alteração da capacidade psicomotora.', '1997-09-23', 59, 468)

on conflict (referencia) do update set 
    texto = excluded.texto, 
    vigencia_de = excluded.vigencia_de, 
    id_materia = excluded.id_materia, 
    id_topico = excluded.id_topico;
